-- database/seed.sql
-- Demo data for TenantGuard local development.
--
-- IMPORTANT: Passwords in this file are PLACEHOLDERS.
-- The real bcrypt hashes are generated by init_db.py from the values in .env.
-- Use init_db.py for actual seeding; use this file only for reference or manual psql runs.
--
-- Usage (psql):
--   psql -U postgres -d tenantguard -f database/schema.sql
--   psql -U postgres -d tenantguard -f database/seed.sql
--
-- To generate a bcrypt hash for a password in Python:
--   python -c "from passlib.context import CryptContext; c=CryptContext(schemes=['bcrypt']); print(c.hash('YOUR_PASSWORD'))"

-- ── Tenants ───────────────────────────────────────────────────────────────────
INSERT INTO tenants (name)
VALUES ('Tenant Alpha')
ON CONFLICT (name) DO NOTHING;

INSERT INTO tenants (name)
VALUES ('Tenant Beta')
ON CONFLICT (name) DO NOTHING;

-- ── Users (hashes must be generated with passlib bcrypt — see note above) ─────
-- Replace the hash strings below with real bcrypt hashes generated from your
-- configured TENANT_A_DEMO_PASSWORD and TENANT_B_DEMO_PASSWORD values.

INSERT INTO users (tenant_id, username, hashed_password)
SELECT t.id,
       'tenant_a_user',
       '$2b$12$REPLACE_WITH_REAL_BCRYPT_HASH_FOR_TENANT_A_PASSWORD'
FROM tenants t
WHERE t.name = 'Tenant Alpha'
ON CONFLICT (username) DO NOTHING;

INSERT INTO users (tenant_id, username, hashed_password)
SELECT t.id,
       'tenant_b_user',
       '$2b$12$REPLACE_WITH_REAL_BCRYPT_HASH_FOR_TENANT_B_PASSWORD'
FROM tenants t
WHERE t.name = 'Tenant Beta'
ON CONFLICT (username) DO NOTHING;

-- ── Invoices ──────────────────────────────────────────────────────────────────
-- Tenant A invoices
INSERT INTO invoices (id, tenant_id, description, amount, notes)
SELECT 101, t.id, 'Invoice A — Cloud Services Q4', 1500.00, 'Demo invoice for Tenant Alpha'
FROM tenants t WHERE t.name = 'Tenant Alpha'
ON CONFLICT (id) DO NOTHING;

INSERT INTO invoices (id, tenant_id, description, amount, notes)
SELECT 102, t.id, 'Invoice A — Support Contract Q4', 750.00, 'Second demo invoice for Tenant Alpha'
FROM tenants t WHERE t.name = 'Tenant Alpha'
ON CONFLICT (id) DO NOTHING;

-- Tenant B invoices
INSERT INTO invoices (id, tenant_id, description, amount, notes)
